import{getTemplate}from"./base_setup_page.html.js";export const NEXT_PAGE_EVENT="next-page";export const CANCEL_SETUP_EVENT="cancel-setup";export class BaseSetupPageElement extends HTMLElement{constructor(){super();const template=document.createElement("template");template.innerHTML=getTemplate();this.attachShadow({mode:"open"}).appendChild(template.content.cloneNode(true))}connectedCallback(){const contentElement=this.shadowRoot.querySelector("#content");this.updateContentFade(contentElement);contentElement.addEventListener("scroll",this.updateContentFade.bind(undefined,contentElement),{passive:true});this.shadowRoot.querySelector("#dialog").focus()}updateContentFade(contentElement){window.requestAnimationFrame((()=>{const atTop=contentElement.scrollTop===0;const atBottom=contentElement.scrollHeight-contentElement.scrollTop===contentElement.clientHeight;contentElement.classList.toggle("fade-top",!atTop);contentElement.classList.toggle("fade-bottom",!atBottom)}))}}